stack_declaration.example:
stack #navbar {
    at: (40px, 40px);
    width: 820px;
    height: 64px;
    direction: horizontal;
    gap: 16px;
    padding: 0 24px;
    align: center;
    justify: space-between;
    fill: #19271D;
    radius: 12px;

    icon #logo { size: 32px; iconName: "star"; fill: #87CC2E; }
    text #navTitle { content: "Velora Nova"; font-size: 18px; color: #ffffff; }
    rect #ctaButton { size: 140px 36px; fill: #87CC2E; radius: 8px; }
}

mode.example:
stack #tagPill {
    direction: horizontal;
    gap: 8px;
    padding: 6px 16px;
    size: hug hug;
    background: alpha(#87CC2E, 0.15);
    radius: 16px;

    circle #statusDot { size: 8px; fill: #87CC2E; }
    text #tagLabel { content: "LIVE SESSION"; font-size: 11px; font-weight: 700; color: #87CC2E; }
}

stack #cardHeader {
    width: 600px;
    direction: horizontal;
    gap: 16px;

    text #title {
        width: fill;
        content: "High-Throughput Streaming Engine";
        font-size: 20px;
    }
    rect #badge {
        width: 100px;
        size: 100px 28px;
    }
}
